VALUES ('North Rukuru Coalfield — Malcoal Operations', 'Malcoal Mining Limited', 'Mining license — Karonga District, North Malawi', NULL, NULL, 'Malawi', 'Northern Region', 'Karonga District, Northern Region, Malawi', -9.95, 33.78, 'Dar es Salaam (Tanzania, ~500km north via road) or Nacala-a-Velha (Mozambique, ~800km southeast)', 'No direct rail — TAZARA at Mbeya, Tanzania (~250km north via road); Malawi rail not connected to Karonga', 2015, NULL, 'Intra Energy Corporation (IEC)', '[{"year": null, "event": "Malcoal Mining Limited established — Intra Energy Corp (IEC, ASX) holds 90% stake"}, {"year": 2016, "event": "HRW documents Malcoal open-pit mine operational in Karonga; noted closed end 2015 but still operational July 2016"}, {"year": 2019, "event": "USGS Minerals Yearbook still lists Malcoal (IEC 90%) as active operator"}]'::jsonb, '[{"year": null, "event": "One of four largest coal mines in Malawi alongside Eland, Mchenga, Kaziwiziwi"}, {"year": 2015, "event": "Combined capacity of all four major mines: 10,000 tonnes/month"}, {"year": null, "event": "Coal exported to Tanzania for cement manufacturing"}, {"year": 2016, "event": "Human rights concerns documented by HRW: communities not consulted on relocation"}]'::jsonb, '[{"year": null, "event": "Community relocation disputes — Malcoal relocated families without proper process per HRW 2016"}, {"year": null, "event": "Promised community infrastructure (schools, clinics, boreholes) not delivered"}, {"year": null, "event": "Environmental issues: open pit on mountain back close to river; acid mine drainage risk"}]'::jsonb, NULL, 'Sub-bituminous', 'Thermal coal — domestic cement, tobacco curing, beverages', 5250, NULL, NULL, NULL, NULL, NULL, NULL, 'Open-pit', NULL, NULL, NULL, NULL, NULL, 'Dar es Salaam (Tanzania, ~500km north via road)', '["Road (M1 northward to Karonga, then north through Tanzania to Dar)", "No rail to Karonga or northern Malawi"]'::jsonb, NULL, false, '[]'::jsonb)
