INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Livingstonia Coalfield — Multiple Operating Mines', 'Kasikizi Coal Mine Ltd; Rukuru Mining Ltd; Coal Products Ltd; Kaziwiziwi Mining Co', 'Multiple mining licenses — 10 issued + 13 prospecting licenses for coal in northern Malawi', 'hr@rukuru.mw', NULL, 'Malawi', 'Northern Region', 'Rumphi District, ~20km north of Mzuzu, Northern Region, Malawi', -10.36, 33.98, 'Nacala-a-Velha (Mozambique, ~700km south via road) or Beira (~900km)', 'No rail to Rumphi — nearest rail is Lilongwe–Blantyre in central/south Malawi; Nacala Corridor >500km south', 1987, 37, 'Mining Investment and Development Corporation', '[{"year": 1987, "event": "Mchenga mine opened by government-owned Mining Investment and Development Corporation"}, {"year": 1999, "event": "Mchenga mine privatized to Coal Products Ltd"}, {"year": 2014, "event": "Rukuru Mining Ltd commences exploration at Chombe Mine site"}, {"year": 2017, "event": "Rukuru Mining commences underground mining at Chombe Coal Mine (room-and-pillar)"}, {"year": 2018, "event": "Kasikizi Coal Mine opens (Mpata, Karonga) — JV Zagaf Cement and Indian companies; becomes largest mine in Malawi"}, {"year": 2022, "event": "Mchenga discloses plans for 100MW Rukuru Coal Power Plant ($287M); subsequently stalled"}, {"year": 2024, "event": "Malawi 10-Year Implementation Plan lists Rukuru power station under slow progress"}]'::jsonb, '[{"year": null, "event": "Mchenga: second-largest mine in Malawi; operational since 1987"}, {"year": 2018, "event": "Kasikizi: largest mine in Malawi; JV between Malawian cement company and Indian investors"}, {"year": 2017, "event": "Chombe (Rukuru Mining): ~20% of national production from standing start"}, {"year": null, "event": "Livingstonia coalfield: highest CVs in Malawi; room-and-pillar underground predominant"}, {"year": null, "event": "Proposed 100MW Rukuru Coal Power Plant — EPC signed with China Power Construction Corp; stalled on PPA"}, {"year": 2025, "event": "AMD documented at Kaziwiziwi tailings pond and Mchenga abandoned workings"}]'::jsonb, '[{"year": 2025, "event": "AMD identified at Kaziwiziwi (tailings pond) and Mchenga (abandoned underground) — pH 4.46–7.02, elevated Fe and SO4"}, {"year": null, "event": "Common hanging roof falls in rainy season across underground operations"}, {"year": null, "event": "Rukuru Power Plant Partial Risk Guarantee from AfDB withdrawn after pressure from European/American funders opposing coal"}]'::jsonb, 17, 'Sub-bituminous (predominantly)', 'Livingstonia yields highest CVs in Malawi', 5250, NULL, NULL, NULL, NULL, 120000, NULL, 'Underground (room-and-pillar) — Mchenga, Kaziwiziwi, Chombe; Surface (open-pit) — Kasikizi', 55, 'FOB mine gate / delivered Malawi', NULL, NULL, NULL, 'Nacala-a-Velha (Mozambique, ~700km south via road to rail junction)', '["Road (M1 south from Rumphi to Lilongwe/Blantyre, then to Mozambique border)", "Nacala Logistics Corridor rail (passes through southern Malawi)", "Lake Malawi barge transport (limited)"]'::jsonb, NULL, false, '["Rukuru Mining: ISO 9001:2015 equivalent"]'::jsonb)
