INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Jerada Coal Mine (Les Charbonnages du Maroc — CDM)', 'CLOSED — Les Charbonnages du Maroc (CDM) until 2001; post-2018 artisanal cooperatives', 'Industrial concession closed 2001; cooperative licenses established 2018–2021', NULL, NULL, 'Morocco', 'Oriental Region', 'Jerada, Province de Jerada, Oriental Region, Morocco', 34.3050, -2.1844, 'Nador (Mediterranean, ~150km north) or Casablanca (~600km west)', 'Railway connection exists — ONCF national rail at Oujda (~60km); historical mine rail to drying plant', 1936, 65, 'Société Chérifienne des Charbonnages de Jérada (SCCD) — Ougrée-Marihaye (Belgian) and BRPM', '[{"year": 1929, "event": "SCCD formed — JV between Ougrée-Marihaye (Belgian) and BRPM; city of Jerada built around mine"}, {"year": 1946, "event": "Charbonnages Nord-Africains (CNA) established — Belgian, French, Moroccan state shareholders"}, {"year": 1967, "event": "Jerada coal-fired power station opened; mine employment peaks ~9,000 workers"}, {"year": 1981, "event": "Company renamed Charbonnages du Maroc (CDM) — 98.89% owned by BRPM"}, {"year": 1985, "event": "World Bank loan ~$27M for modernization — target 1Mtpa by 1988"}, {"year": 1990, "event": "Production decline begins — deep seams >920m, safety issues, high costs"}, {"year": 1998, "event": "CDM effective closure announced"}, {"year": 2001, "event": "CDM officially closes Jerada mine — bankruptcy; 15-20Mt CMWR left without rehabilitation"}, {"year": 2017, "event": "Hirak de Jerada — two brothers die in informal mine; near-daily protests"}, {"year": 2018, "event": "Government establishes artisanal cooperative system; PM Othmani visits; four illegal politician licenses withdrawn"}, {"year": 2023, "event": "Three miners die from suffocation in cooperative-licensed coal well (August)"}]'::jsonb, '[{"year": null, "event": "City of Jerada built entirely for and around coal mine — 43,916 population"}, {"year": null, "event": "Peak production ~800,000 tpa anthracite; World Bank target 1Mtpa by 1988 (never achieved)"}, {"year": null, "event": "USGS: ~650,000 tonnes anthracite in later operational years"}, {"year": null, "event": "Only coal mine ever operated in Morocco at industrial scale"}, {"year": null, "event": "15-20Mt CMWR piles remain — studies examining reprocessing potential"}, {"year": null, "event": "Post-closure informal mining continues with significant human cost"}]'::jsonb, '[{"year": 2017, "event": "Hirak de Jerada: two brothers died in informal mine; political crisis; PM emergency visit"}, {"year": 2023, "event": "August: three miners die from suffocation in cooperative-licensed well"}, {"year": null, "event": "Multiple deaths annually in informal sandriyat — described as city mines of death"}, {"year": null, "event": "AMD / groundwater contamination from CMWR piles — elevated sulfates from pyrite oxidation"}]'::jsonb, NULL, 'Anthracite', 'High rank, low volatile — ASTM Anthracite', 8000, NULL, NULL, NULL, NULL, 0, 0, 'Former: underground (deep shaft, room-and-pillar). Current: informal shallow pit/sandriyat by artisanal miners', NULL, NULL, NULL, NULL, NULL, 'Nador (Mediterranean, ~150km north) or Casablanca (Atlantic, ~600km west)', '["Rail: ONCF connection at Oujda (~60km)", "Road: N17 (Oujda–Jerada–Bouarfa)"]'::jsonb, NULL, false, '[]'::jsonb)
