INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Moatize Coal Mine (Mina Carvao Moatize)', 'Vulcan Mozambique SA', 'Mining Concession — Moatize District, Tete Province; expires 2032 (extendable 25 years)', NULL, NULL, 'Mozambique', 'Tete Province', 'Moatize District, Tete Province, Mozambique', -16.12, 33.72, 'Nacala-a-Velha (912km via NLC rail) — primary; Beira (660km via Sena Railway) — secondary', 'Nacala Logistics Corridor: Moatize to southern Malawi to Nacala-a-Velha (912km, 18Mtpa). Sena Railway: Moatize to Beira (660km, 6Mtpa).', 2011, 14, 'Vale S.A.', '[{"year": 2006, "event": "Vale granted mining concession; begins development planning"}, {"year": 2011, "event": "Mine inaugurated May 2011; first coal production; first coal to Beira by train August 2011"}, {"year": 2014, "event": "Vale sells ~15% stake and 35% of NLC to Mitsui for ~$690M"}, {"year": 2017, "event": "Vale transfers 15% Moatize + 50% NLC to Mitsui for $690M; peak production 11.3Mt"}, {"year": 2021, "event": "Vale announces exit from coal; buys back Mitsui stake for $1"}, {"year": 2021, "event": "December: Vale agrees to sell Moatize + NLC to Vulcan Minerals (Jindal) for $270M"}, {"year": 2022, "event": "April 25: Vale-Vulcan sale completed; Vulcan Mozambique SA becomes operator"}, {"year": 2023, "event": "Vulcan reports >35Mt cumulative over 3 years since takeover"}]'::jsonb, '[{"year": null, "event": "Vale largest-ever coal venture; $2B+ initial investment"}, {"year": null, "event": "Nacala Logistics Corridor: 912km rail + Nacala port ($4.4B total infrastructure)"}, {"year": null, "event": "Capacity: 22 million tpa (current nameplate after expansion)"}, {"year": 2019, "event": "Proven and probable reserves: 913.8Mt; marketable: 364.9Mt"}, {"year": null, "event": "Mine life: 35 years (from 2011 = expected to 2046)"}, {"year": null, "event": "Largest employer in Mozambique; 8,000+ workers under Vale"}, {"year": 2023, "event": "Vulcan: >35Mt/year over 3 years since April 2022 takeover"}, {"year": null, "event": "New CHPP under construction — 26Mtpa processing capacity"}]'::jsonb, '[{"year": null, "event": "Displacement of thousands of Moatize residents — bitter complaints about substandard resettlement housing"}, {"year": null, "event": "Ntchenga and Mpandwe communities being relocated ($20M Nhamitsatsi resettlement — 200 families)"}, {"year": 2022, "event": "Strike by ~10% of workforce"}, {"year": null, "event": "Multiple resettlement legal disputes throughout Vale era"}]'::jsonb, 21, 'Metallurgical (coking) and Thermal — both', 'Premium Hard Coking Coal (PHCC); CSR 68-71', NULL, NULL, NULL, NULL, NULL, 22000000, NULL, 'Open-pit (large-scale)', 206, 'FOB Australia equivalent (reference price for coking coal CSR 68-71)', NULL, NULL, 'Long-term off-take (steel mills); spot', 'Nacala-a-Velha (primary — dedicated coal terminal, 18Mtpa) or Beira (secondary, 6Mtpa)', '["Nacala Logistics Corridor rail — 912km to Nacala-a-Velha; 101 locomotives, 2,677 wagons", "Sena Railway — 660km to Beira; secondary/backup"]'::jsonb, NULL, true, '["ISO 9001:2015", "ISO 14001:2015", "ISO 45001:2018 (Bureau Veritas Africa)"]'::jsonb)
