VALUES ('Cahora Bassa Coalfield — Chirodzi Coal Mine (Jindal / JSPL)', 'JSPL Mozambique Minerals Limitada', '25-year mining concession — 21,540 hectares, Cahora Bassa District', NULL, NULL, 'Mozambique', 'Tete Province', 'Chirodzi, Cahora Bassa District, Tete Province, Mozambique', -15.87, 32.58, 'Beira (~450km via Sena Railway) or Nacala-a-Velha (~700km)', 'Sena Railway (Tete to Beira, ~450km) — primary export route', 2012, 12, 'JSPL Mozambique Minerals Limitada', '[{"year": 2008, "event": "JSPL incorporated JSPL Mozambique; began coal prospection at Chirodzi"}, {"year": 2010, "event": "Mozambique state radio announces ~1 billion tonnes coal in Cahora Bassa District"}, {"year": 2010, "event": "August: JSPL announces 1.65 billion tonnes reserves confirmed"}, {"year": 2011, "event": "October: Government authorizes JSPL studies for 2,640MW Jindal Tete Power Station"}, {"year": 2012, "event": "November: JSPL starts coking coal production at Chirodzi"}, {"year": 2013, "event": "October 18: Chirodzi mine officially opened; estimated reserves 1.2 billion tonnes"}, {"year": 2020, "event": "JSPL plans production increase to 4.5Mtpa; expansion commissioned"}, {"year": 2021, "event": "JSPL FY21: Chirodzi operating at 5Mt/y; 2x75MW power plant under discussion"}]'::jsonb, '[{"year": 2010, "event": "1.65 billion tonnes reserves announced — one of largest in sub-Saharan Africa"}, {"year": 2013, "event": "1.2 billion tonnes confirmed reserve on mine opening"}, {"year": null, "event": "25-year mining concession over 21,540 ha"}, {"year": 2021, "event": "Operating at 5Mt/year"}, {"year": null, "event": "Planned 2x75MW mine-mouth power plant (discussions ongoing)"}, {"year": null, "event": "Coal exported to support JSPL steel plants in central India"}]'::jsonb, '[{"year": null, "event": "Major constraint: distance from mine to rail terminal in Tete city"}, {"year": null, "event": "Power plant plans repeatedly scaled down: 2,640MW (2011) to 2x75MW (2021)"}]'::jsonb, 40, 'Semi-hard coking coal (metallurgical) and thermal coal', 'Semi-hard coking coal for steel plants', NULL, NULL, NULL, NULL, NULL, 5000000, NULL, 'Open-pit (open-cast)', NULL, 'FOB Beira (primary export port)', NULL, NULL, 'Captive (JSPL India internal); potentially open to third-party', 'Beira (primary — Sena Railway) or Nacala-a-Velha (longer)', '["Road: Chirodzi to Tete city (~120km)", "Sena Railway: Tete to Beira (660km) — primary export route"]'::jsonb, NULL, true, '[]'::jsonb)
