VALUES ('Mucanha-Vuzi Coalfield', 'No active mining — explored by Vale 2008-2012; concession status post-Vale exit unclear', 'Exploration/mining concession — Cahora Bassa District, Tete Province', NULL, NULL, 'Mozambique', 'Tete Province', 'Northern shore of Cahora Bassa dam, Cahora Bassa District, Tete Province, Mozambique', -15.57, 32.13, 'Beira (~550km via road south through Tete) or Nacala-a-Velha (~700km+)', 'No direct rail — nearest rail is Sena Railway at Tete city (~150km southeast)', NULL, 0, 'Vale Mozambique (explorer)', '[{"year": 1980, "event": "Initial exploration of Bohodzi block by CPRM (Brazilian state)-led consortium"}, {"year": 2008, "event": "Vale begins comprehensive exploration: airborne survey, geological mapping, drilling"}, {"year": 2012, "event": "Vale completes exploration — extends coal sequence to 26km E-W strike (Grande Mucanha, Mucanha Oeste blocks)"}, {"year": 2014, "event": "Coaltrans reports government lists Mucanha Vuzy as Vale-linked development with 11Mtpa potential"}, {"year": 2022, "event": "Vale exits Mozambique coal; Mucanha-Vuzi concession status post-Vale unclear"}, {"year": 2025, "event": "No mining operations; no development announcements"}]'::jsonb, '[{"year": null, "event": "32 coal seams identified across 3 blocks; grouped into 8 major seams"}, {"year": null, "event": "Seam thickness: 0.5m to 8.5m (individual seams)"}, {"year": 2012, "event": "26km E-W strike length confirmed by Vale drilling"}, {"year": 2017, "event": "Estimated reserves: 3,600Mt (Mining Weekly) — one of largest undeveloped deposits globally"}, {"year": null, "event": "Coal quality analyses completed by Vale 2008-2012 — results proprietary"}]'::jsonb, '[{"year": null, "event": "No production incidents — deposit never mined"}, {"year": null, "event": "Severely block-faulted structure complicates development"}]'::jsonb, NULL, 'Coking and thermal coal (Moatize Formation correlation)', 'Probable hard coking coal component; not confirmed publicly', NULL, NULL, NULL, NULL, NULL, 0, 0, 'Not determined — open-pit likely given geological similarity to Moatize', NULL, NULL, NULL, NULL, NULL, 'Beira (~550km — via new road/rail development required)', '["Road (currently only option; 150+km to nearest rail at Tete)", "No rail within 150km — new rail construction required"]'::jsonb, NULL, false, '[]'::jsonb)
